import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import X from '../img/X.png';

function Order({ toggleCart }) {
    const [cart, setCart] = useState([]);
    const navigate = useNavigate();

    useEffect(() => {
        if (localStorage.cart) {
            const cartItems = JSON.parse(localStorage.getItem('cart')) || [];
            setCart(cartItems);
        }
    }, []);

    const calculateTotal = () => {
        return cart.reduce((total, item) => total + item.items.reduce((subTotal, subItem) => subTotal + (subItem.price * subItem.count), 0), 0);
    };

    React.useEffect(() => {
        // Disable scrolling on the main page when the cart is open
        document.body.style.overflow = 'hidden';
        // Re-enable scrolling when the Order component is unmounted
        return () => {
            document.body.style.overflow = 'auto';
        };
    }, []); // Effect is called only on component mount

    async function PayOrder(event) {
        event.preventDefault();

        if (localStorage.orderId) {
            try {
                const response = await fetch(`${process.env.REACT_APP_ORDER_SERVICE_URL}/order/pay`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': 'Bearer ' + localStorage.token
                    },
                    body: JSON.stringify({
                        "orderId": localStorage.orderId
                    }),
                });
                const data = await response.json();
                console.log(data);

                if (data.success === true) {
                    localStorage.removeItem('orderId');
                    localStorage.removeItem('cart');
                    localStorage.order = false;
                    alert("Спасибо за покупку!");
                    window.location.reload();
                } else if (data.message === "NOT_ENOUGH_TOKENS") {
                    alert("У вас недостаточно токенов");
                } else if (data.message === "NO_SUBSCRIPTION") {
                    alert("У вас нету подписки");
                    navigate('/Subscription');
                }
            } catch (error) {
                console.error('Error pay order:', error);
                alert('Произошла ошибка при оплате корзины');
            }
        }
    }

    async function CancelOrder(event) {
        event.preventDefault();

        if (localStorage.orderId) {
            try {
                const response = await fetch(`${process.env.REACT_APP_ORDER_SERVICE_URL}/order/cancel`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': 'Bearer ' + localStorage.token
                    },
                    body: JSON.stringify({
                        "orderId": localStorage.orderId
                    }),
                });
                const data = await response.json();
                console.log(data);

                if (data.success === true || data.message === "Cannot cancel order because status is not PENDING") {
                    localStorage.removeItem('orderId');
                    localStorage.removeItem('cart');
                    localStorage.order = false;
                    window.location.reload();
                }
            } catch (error) {
                console.error('Error cancelling order:', error);
                alert('Произошла ошибка при очистке корзины');
            }
        }
    }

    async function CancelOrderItem(orderItemId) {
        console.log(orderItemId);

        if (localStorage.orderId) {
            try {
                const response = await fetch(`${process.env.REACT_APP_ORDER_SERVICE_URL}/order-item/cancel`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Authorization': 'Bearer ' + localStorage.token
                    },
                    body: JSON.stringify({
                        "orderItemId": orderItemId
                    }),
                });
                const data = await response.json();
                console.log(data);

                if (data.success === true) {
                    const updatedCart = cart.map(item => {
                        if (item.toyId === orderItemId) {
                            const updatedItems = item.items.filter(subItem => subItem.orderItemId !== orderItemId);
                            return { ...item, items: updatedItems, count: updatedItems.length };
                        }
                        return item;
                    }).filter(item => item.items.length > 0);

                    localStorage.setItem('cart', JSON.stringify(updatedCart));
                    setCart(updatedCart);
                    if (updatedCart.length === 0) {
                        CancelOrder();
                    }
                    window.location.reload();
                }
            } catch (error) {
                console.error('Error cancelling order item:', error);
                alert('Произошла ошибка при удалении товара из корзины');
            }
        }
    }

    return (
        <div className="order-overlay" onClick={toggleCart}>
            <div className="order" onClick={e => e.stopPropagation()}>
                <Link className='back-link' id="button" onClick={toggleCart}>🠈НАЗАД</Link>
                <div className='Order-clear'>
                    <h1>Корзина</h1>
                    <img src={X} className="crossIcon" alt="" />
                    <h2 onClick={CancelOrder}>Очистить корзину</h2>
                </div>
                {cart.length > 0 ? (
                    <div className="cart-items">
                        {cart.map(item => (
                            <div key={item.toyId} className="cart-item">
                                <h2>{item.name}</h2>
                                {item.items.map(subItem => (
                                    <div key={subItem.orderItemId} className="cart-subitem">
                                        <img onClick={() => CancelOrderItem(subItem.orderItemId)} src={X} className="crossIcon" alt="" />
                                        <img src={`${process.env.REACT_APP_TOY_SERVICE_URL}/Images/${subItem.imageUrl}`} alt={subItem.name} />
                                        <div className='cart-text'>
                                            <div className="cart-item-details">
                                                <p>{subItem.price} Токенов</p>
                                            </div>
                                            <div className='cart-item-count'></div>
                                            <p>Количество: {subItem.count}</p>
                                        </div>
                                    </div>
                                ))}
                                <p>Общее количество: {item.count}</p>
                            </div>
                        ))}
                    </div>
                ) : (
                    <p>Корзина пуста</p>
                )}
                {cart.length > 0 && (
                    <div className="total-sum">
                        <h2>Итого: {calculateTotal()} Токенов</h2>
                    </div>
                )}
                <div className="payment-button-container">
                    <button className="payment-button" onClick={PayOrder}>Оплатить</button>
                </div>
            </div>
        </div>
    );
}

export default Order;
